function euclid(a,b){ var s=0; for(var i=0;i<a.length;i++){ var d=a[i]-b[i]; s+=d*d; } return Math.sqrt(s); }
function cluster(points, k){ var n=points.length; var clusters=[]; for(var i=0;i<n;i++) clusters.push([i]);
  function dist(ci,cj){ var m=Infinity; for(var a=0;a<ci.length;a++) for(var b=0;b<cj.length;b++){ var d=euclid(points[ci[a]],points[cj[b]]); if(d<m) m=d; } return m; }
  while(clusters.length>k){
    var mi=0,mj=1,mn=Infinity;
    for(var i=0;i<clusters.length;i++) for(var j=i+1;j<clusters.length;j++){ var d=dist(clusters[i],clusters[j]); if(d<mn){mn=d;mi=i;mj=j;} }
    clusters[mi]=clusters[mi].concat(clusters[mj]); clusters.splice(mj,1);
  }
  return clusters; }
var EXPORTS={cluster:cluster, euclid:euclid};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.HierarchicalClusteringForgePure = EXPORTS; }
